import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';

import { LandingRoutingModule } from './landing-routing.module';

@NgModule({
  declarations: [
  LandingComponent
  ],
  imports: [
    CommonModule,
    LandingRoutingModule
  ],
  exports:[
    LandingComponent
  ]
})
export class LandingModule { }
